import{_ as p,a0 as s,w as l,s as i,ao as m,I as a,x as o,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux中的more命令－逐页显示长文本文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中的more命令－逐页显示长文本文件 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中的more命令－逐页显示长文本文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中的more命令－逐页显示长文本文件 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Linux more Command - Display Long Text File Per page at a Time","title":"Linux中的more命令－逐页显示长文本文件","tag":"201403","desc":""},"relativePath":"201403/Linux more Command - Display Long Text File Per page at a Time.md","filePath":"[post].md"}'),d={name:"201403/Linux more Command - Display Long Text File Per page at a Time.md"};function g(c,e,h,x,u,_){const r=s("Link");return l(),i("div",null,[e[11]||(e[11]=m(`<h1 id="linux中的more命令-逐页显示长文本文件" tabindex="-1">Linux中的more命令－逐页显示长文本文件 <a class="header-anchor" href="#linux中的more命令-逐页显示长文本文件" aria-label="Permalink to “Linux中的more命令－逐页显示长文本文件”">​</a></h1><p>如果你已经习惯了在Linux系统上工作，那你一定会发现在Linux世界中存在着大量的文本文件。配置文件和日志文件通常都采用文本格式。这些文件通常都有很长的内容，不能在一屏内全部显示。所以在处理这种文件时，我们需要分页显示。这时我们可以用上<strong>more</strong>命令。</p><h3 id="more是干嘛的" tabindex="-1">more是干嘛的 <a class="header-anchor" href="#more是干嘛的" aria-label="Permalink to “more是干嘛的”">​</a></h3><p>more是一个用来分页显示大文本文件的命令，它默认是内置在各个Linux发行版中的。</p><h3 id="怎么用more" tabindex="-1">怎么用more <a class="header-anchor" href="#怎么用more" aria-label="Permalink to “怎么用more”">​</a></h3><p>使用more命令，只需要键入:</p><pre><code>$ more file_name
</code></pre><p>比如，我们想检查/var/log目录下的日志文件syslog，只需要键入：</p><pre><code>$ more /var/log/syslog
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more.png" alt="more命令"></p><p>然后我们可以看到<strong>在屏幕左下角有个提示</strong>，告诉我们当前的显示比例为0%。看上去这个文件相当大，所以第一页是全部页数的0%。使用空格键可以往下翻页，然后就可以看到提示的百分比会增加。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_2.png" alt="Scroll page"></p><h3 id="限制每页显示的行数" tabindex="-1">限制每页显示的行数 <a class="header-anchor" href="#限制每页显示的行数" aria-label="Permalink to “限制每页显示的行数”">​</a></h3><p>在执行more命令的时候，它会占用你终端窗口的全部空间用于显示。但是你可以通过参数<strong>-数字</strong>来限制每页显示的行数。</p><p>例如，你希望每页<strong>限制显示12行</strong>，可以通过下面的命令：</p><pre><code>$ more -12 /var/log/syslog
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_12.png" alt="限制每页显示12行"></p><p>现在，你会看到每页只显示12行，在按下空格键后，就会翻页显示后面的12行。</p><h3 id="display-user-message" tabindex="-1">Display user message <a class="header-anchor" href="#display-user-message" aria-label="Permalink to “Display user message”">​</a></h3><p>我们知道，more命令会在显示区域的左下角提示当前内容所占的百分比。对于第一次使用more命令的人来说，他或她可能会想知道怎么才能往下翻页。为了避免这种情况，我们可以在执行时增加<strong>-d</strong>参数，这样就会额外显示一行用户信息“[<strong>按空格键继续，‘q‘推出.</strong>]”</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_d1.png" alt="More with -d option"></p><p>如果用户按了<strong>‘空格‘或’q‘</strong>之外的按键，more会显示一行帮助信息<strong>“ [按‘h’键查看提示。]”</strong></p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_d2.png" alt="More displaying help message"></p><p>如果按下h键，会显示一个帮助信息：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_dh.png" alt="Display help"></p><p>一个有意思的指令是<strong>b</strong>按钮，<strong>b按钮允许你</strong>退回到前面的页面。换句话说，b按钮可以允许<strong>向前翻页</strong>。</p><p>你可以通过左上角的<strong>...前1页</strong>信息来确认当前显示的是前面的页面。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_back.png" alt="在more中往前翻页"></p><h3 id="禁止滚动" tabindex="-1">禁止滚动 <a class="header-anchor" href="#禁止滚动" aria-label="Permalink to “禁止滚动”">​</a></h3><p>通过参数<strong>-c</strong>，more命令不会滚动页面，而是直接清除之前的内容，替换为下一页的内容。 With <strong>-c</strong> option, more will not scroll the page. It will clear the previous page and put the next page or lines there.</p><pre><code>$ more -10 -c lynis.log
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_c.png" alt="Suppress scroll"></p><p>如果按下空格键，下一页会仍然有相同的大小。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_c2.png" alt="Suppress scroll"></p><h3 id="忽略多余的空白行" tabindex="-1">忽略多余的空白行 <a class="header-anchor" href="#忽略多余的空白行" aria-label="Permalink to “忽略多余的空白行”">​</a></h3><p>使用参数<strong>-s</strong>来忽略多余的空白行，下面是个例子：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_s.png" alt="多个空白行的文件"></p><p>当我们增加参数<strong>-s</strong>后：</p><pre><code>$ more -s doc_30.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_s2.png" alt="忽略了多余空白行"></p><h3 id="查找字符串" tabindex="-1">查找字符串 <a class="header-anchor" href="#查找字符串" aria-label="Permalink to “查找字符串”">​</a></h3><p>如果你的日志文件非常大，那么在其中查找你想要的字符串并不是那么容易。more命令的查找功能可以帮你，通过参数<strong>+/string</strong>可以用来搜索字符串，找到的关键字会显示在第一行。比如我们要在<strong>/var/logs/syslog</strong>文件中搜索“<strong>dhclient</strong>”，那more命令的格式：</p><pre><code>$ more +/dhclient /var/log/syslog
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_string.png" alt="查找字符串"></p><p>然后，如果要在文件中继续搜索下一个，只需要按下<strong>/按钮</strong>，后面跟有关键字dhclient。</p><h3 id="从指定行开始显示" tabindex="-1">从指定行开始显示 <a class="header-anchor" href="#从指定行开始显示" aria-label="Permalink to “从指定行开始显示”">​</a></h3><p>你也可以通过参数<strong>+数字</strong>来指定开始显示的行，例如，我们有一个15行的文件：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_num1.png" alt="多行文件"></p><p>然后我们想从第5行开始显示这个文件的内容，命令看起来会是这个样子：</p><pre><code>$ more +5 doc_30.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_num2.png" alt="从指定行开始显示"></p><h3 id="可以显示二进制文件吗" tabindex="-1">可以显示二进制文件吗? <a class="header-anchor" href="#可以显示二进制文件吗" aria-label="Permalink to “可以显示二进制文件吗?”">​</a></h3><p><strong>答案是不行</strong>. more命令会提示这样的信息，例如：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/more_binary.png" alt="显示二进制文件"></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>more是一个用来查看文本文件的基础工具，它不能用来显示二进制文件。通常，我们可以通过命令<strong>man more</strong>或者<strong>more --help</strong>来获取更多关于more怎么使用的信息。</p><hr>`,57)),a("p",null,[e[1]||(e[1]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-command/linux-more-command/"},{default:n(()=>[...e[0]||(e[0]=[o("http://linoxide.com/linux-command/linux-more-command/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=o("译者：",-1)),t(r,{href:"https://github.com/zpl1025"},{default:n(()=>[...e[2]||(e[2]=[o("zpl1025",-1)])]),_:1}),e[5]||(e[5]=o(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[o("LCTT",-1)])]),_:1}),e[9]||(e[9]=o(" 原创翻译，",-1)),t(r,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[o("Linux中国",-1)])]),_:1}),e[10]||(e[10]=o(" 荣誉推出",-1))])])}const L=p(d,[["render",g]]);export{b as __pageData,L as default};
